class PadnoneTests(TestCase):
    def test_basic(self):
        iterable = range(2)
        for func in (mi.pad_none, mi.padnone):
            with self.subTest(func=func):
                p = func(iterable)
                self.assertEqual(
                    [0, 1, None, None], [next(p) for _ in range(4)]
                )

def test_invalid_none_values(self):
    for element, iterable in (
        ((None,), [1, 2]),
        ((1, None), [1, 2]),
        ((1, None), [None, 1]),
        ((None, 2), [1, None]),
    ):
        with self.subTest(element=element, iterable=iterable):
            with self.assertRaises(ValueError):
                mi.combination_with_replacement_index(element, iterable)

def test_none_values(self):
    for iterable in (
        [None, 1, 2],
        [1, None, 2],
        [1, 2, None],
        [None, 1, None],
    ):
        for r in range(4):
            first_index = {}
            for index, element in enumerate(
                combinations_with_replacement(iterable, r)
            ):
                with self.subTest(iterable=iterable, element=element):
                    actual = mi.combination_with_replacement_index(
                        iter(element), iter(iterable)
                    )
                    expected = first_index.setdefault(element, index)
                    self.assertEqual(actual, expected)

def test_reversed_is_none(self):
    # See https://github.com/more-itertools/more-itertools/issues/1001
    class ReversedIsNone:
        __reversed__ = None

        def __iter__(self):
            return iter([1])

    self.assertEqual(mi.last(ReversedIsNone()), 1)

def test_odd(self):
    iterable = (x for x in '012')
    self.assertEqual(
        list(mi.intersperse(None, iterable)), ['0', None, '1', None, '2']
    )
